      { href: "/services/teeth-whitening-amman", label: { en: "Teeth Whitening in Amman", ar: "تبييض الأسنان في عمّان" }, description: { en: "When whitening may be enough before veneers.", ar: "متى قد يكون التبييض كافياً قبل الفينير." } },
      { href: "/services/orthodontics-amman", label: { en: "Orthodontics in Amman", ar: "تقويم الأسنان في عمّان" }, description: { en: "Alignment can make veneer treatment more conservative.", ar: "قد يجعل التقويم خطة الفينير أكثر محافظة." } }
